    fullDescriptionHtml: "<p>The Edwards Cryogenic technology portfolio delivers extreme high-speed pumping of all gases including water vapor, argon, and nitrogen for thin film sputtering, space simulation, and semiconductor fabrication. Driven by closed-cycle Gifford-McMahon (GM) refrigeration, the ECP cryopump range delivers water vapor pumping speeds up to 30,000 L/s without contaminating cleanroom environments. Paired with high-reliability ECC5000 water-cooled and air-cooled helium compressors and ECH precision cold heads down to 10 Kelvin, this platform ensures maximum uptime and rapid thermal regeneration.</p>",
